"""FastAPI app generated by intpot."""


from pathlib import Path

from fastapi import FastAPI as _intpot_fastapi_FastAPI, Body as _intpot_fastapi_Body

UNIT_PRICE = 25

def quote_total(quantity: int, discount: int) -> int:
    subtotal = quantity * UNIT_PRICE
    if discount > subtotal:
        raise ValueError('discount exceeds subtotal')
    return subtotal - discount

app = _intpot_fastapi_FastAPI(title='batch_quote')
_intpot_required = object()


def _quote_impl(
    quantity: int = _intpot_required,
    discount: int = 0,
    receipt: str = '',
) -> dict:
    """Quote a bounded batch, optionally writing a receipt after validation."""
    if quantity is _intpot_required:
        raise TypeError('Missing required argument: quantity')
    total = quote_total(quantity, discount)
    if receipt:
        Path(receipt).write_text(str(total), encoding='utf-8')
    return {'result': total}


@app.post(
    '/quote',
    name='quote',
    summary='Quote a bounded batch, optionally writing a receipt after validation.',
    description='Quote a bounded batch, optionally writing a receipt after validation.',
)
def quote(
    quantity: int = _intpot_fastapi_Body(..., alias='quantity', ge=1, le=10),
    discount: int = _intpot_fastapi_Body(default=0, alias='discount', ge=0),
    receipt: str = _intpot_fastapi_Body(default='', alias='receipt'),
) -> dict:
    """Quote a bounded batch, optionally writing a receipt after validation."""

    return _quote_impl(quantity, discount, receipt)


if __name__ == "__main__":
    import uvicorn as _intpot_api_uvicorn

    # Loopback only. Change to "0.0.0.0" to expose this on the network.
    _intpot_api_uvicorn.run(app, host="127.0.0.1", port=8000)
